def rough_token_estimate(text: str) -> int:
    # a crude heuristic only, real tokenizers are model specific
    return max(1, len(text) // 4)

print(rough_token_estimate("Please summarize the attached document."))
print(rough_token_estimate('{"tool": "search", "params": {"query": "refund policy"}}'))

def check_budget(layer_name: str, current_tokens: int, budget: dict):
    limit = budget[layer_name]
    if current_tokens > limit:
        return False, f"{layer_name} over budget: {current_tokens} > {limit}"
    return True, "ok"

ok, message = check_budget("resource_contents", 15000, budget)
if not ok:
    print("need to trim or summarize before continuing:", message)
